#!/usr/bin/env ruby
require 'json';require 'fileutils'
root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);files=Dir.glob(File.join(client,'**/.DS_Store'),File::FNM_DOTMATCH);checks={nonePresent:files.empty?,clientIgnored:File.read(File.join(client,'.gitignore')).lines.map(&:strip).include?('.DS_Store'),serverIgnored:File.read(File.join(root,'.gitignore')).lines.map(&:strip).include?('.DS_Store'),releaseIgnored:File.read(File.join(root,'.releaseignore')).lines.map(&:strip).include?('**/.DS_Store')};report={schemaVersion:1,remaining:files.map{|p|p.delete_prefix(client+'/')},checks:checks,passed:checks.values.all?};out=File.join(root,'docs/generated/chyg07-ds-store.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");abort "CHYG07 failed: #{checks}" unless report[:passed];puts 'CHYG07 PASS: .DS_Store removed and blocked from source/release'
